arguments.argument:
fn_message_receive(global.socket)

if !check{exit}

if alarm[0]>0
{
    while(1)
    {
        if alarm[0]<current_time-(check_map_var*1000)
        {
            ds_list_add(sys_wait_key.key, room_speed*10)
            ds_list_add(sys_wait_key.key, 9)
            ds_list_add(sys_wait_key.key, "[SYSTEM] "+string(5-check_map_var)+" seconds to start the game.")
            check_map_var+=1
            if check_map_var=6
            {
                room_goto(mapid[map])
                break;
            }
            sound_play(ml_sound0)
            screen_redraw()
        }
        else{break}
    }
}
